/**
 * Filter chips (spec/02 §2.9). [labels] are the words, [selected] the chosen indices, [onChange] gets the new set.
 * [single] = Einfachwahl: exactly one chosen, pressing another moves the choice. [groupLabel] names the group; with
 * [showLabel] it stands above as a field's label, [optional] adds „(optional)“. [max] (multiple choice) = the most that
 * can be chosen: at the limit the others are disabled and „Höchstens 3 auswählbar.“ stands under the group.
 * [disabledOptions] cannot be chosen ([disabledReason] under the group). [help] and [error] as a field's notes.
 * [clickLabels] = the verb TalkBack says for each chip.
 */
@Composable
fun SbChips(
    labels: List<String>,
    selected: Set<Int>,
    onChange: (Set<Int>) -> Unit,
    groupLabel: String,
    modifier: Modifier = Modifier,
    single: Boolean = false,
    showLabel: Boolean = false,
    optional: Boolean = false,
    max: Int? = null,
    disabledOptions: Set<Int> = emptySet(),
    disabledReason: String? = null,
    help: String? = null,
    error: String? = null,
    clickLabels: List<String>? = null,
) {
    val t = SebaroTheme.tokens
    val c = SebaroTheme.colors
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val limit = max?.takeIf { !single && selected.size >= it }
    val full = limit != null
    val name = if (optional && !showLabel) "$groupLabel, ${m.fieldOptional}" else groupLabel
    val notes = listOfNotNull(
        limit?.let { m.chipsMax(sbFormatCount(it)) },
        disabledReason?.takeIf { disabledOptions.isNotEmpty() },
        help,
    )
    Column(modifier, verticalArrangement = Arrangement.spacedBy(t.space.s1)) {
        if (showLabel) SbFieldLabel(groupLabel, optional, enabled = true)
        SbFlowRow(
            Modifier
                .semantics {
                    // a drawn label is read already („Tageszeit, optional“); the group repeats no name then
                    if (!showLabel) contentDescription = name
                    isTraversalGroup = true
                }
                .then(if (single) Modifier.selectableGroup() else Modifier),
            horizontalArrangement = Arrangement.spacedBy(t.space.s2),
        ) {
            labels.forEachIndexed { index, label ->
                val chosen = index in selected
                val on = index !in disabledOptions && (chosen || !full)
                SbChip(label, chosen, single, on, clickLabels?.getOrNull(index)) {
                    onChange(
                        when {
                            single -> setOf(index)
                            chosen -> selected - index
                            else -> selected + index
                        },
                    )
                }
            }
        }
        if (error != null) SbFieldNotes(help = null, counter = null, error = error, spoken = true)
        notes.forEach { Text(it, style = ty.caption, color = c.textMuted) }
    }
}

/**
 * One chip: 48 dp target, a frame of at least 36 dp; chosen = 3 dp accent bottom edge + check + title weight + link
 * colour; [enabled] false = word textMuted, frame border, no target. The word wraps at large text, the chip grows.
 */
@Composable
private fun SbChip(label: String, chosen: Boolean, single: Boolean, enabled: Boolean, clickLabel: String?, press: () -> Unit) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val shape = t.shapes.control
    val frame = when {
        !enabled -> c.border
        pressed || hovered -> c.text
        else -> c.borderStrong
    }
    val ink = when {
        !enabled -> c.textMuted
        chosen -> c.link
        else -> c.text
    }
    val edge = t.borderWidth.strong
    val target = if (single) {
        Modifier.selectable(selected = chosen, interactionSource = interaction, indication = null, enabled = enabled, role = Role.RadioButton, onClick = press)
    } else {
        Modifier.toggleable(value = chosen, interactionSource = interaction, indication = null, enabled = enabled, role = Role.Checkbox, onValueChange = { press() })
    }
    Box(
        Modifier
            .heightIn(min = t.size.targetTouch)
            .then(target)
            .then(
                if (clickLabel != null && enabled) {
                    Modifier.semantics {
                        this[SemanticsActions.OnClick] = AccessibilityAction(clickLabel) {
                            press()
                            true
                        }
                    }
                } else {
                    Modifier
                },
            )
            // a grown chip keeps 4 dp to the next row (at font scale 1 the 48 dp target holds the 36 dp frame anyway)
            .padding(vertical = t.space.s1),
        contentAlignment = Alignment.Center,
    ) {
        Row(
            Modifier
                .sbFocusRing(interaction, t.radius.control)
                .heightIn(min = t.size.targetTouch - t.space.s3)
                .clip(shape)
                .drawWithContent {
                    drawContent()
                    if (chosen) drawRect(if (enabled) c.accent else c.borderStrong, Offset(0f, size.height - edge.toPx()), Size(size.width, edge.toPx()))
                }
                .border(t.borderWidth.control, frame, shape)
                .padding(horizontal = t.space.s3, vertical = t.space.s1),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(t.space.s1),
        ) {
            if (chosen) Icon(SebaroIcons.Outline16.Check, contentDescription = null, tint = ink, modifier = Modifier.size(t.size.iconSm))
            // §14.9: the word wraps at large text, the chip grows; never cut
            SbWrapText(label, ty.label.copy(fontWeight = if (chosen) ty.title.fontWeight else ty.caption.fontWeight), ink)
        }
    }
}
